psql postgresql://postgres:postgres@127.0.0.1:55322/postgres -P pager=off -c "select left(t.title,28) title, t.is_goal g, t.bucket, t.context ctx, t.scope, to_char(t.month_start,'MM-DD') mon, to_char(t.season_start,'MM-DD') sea, to_char(t.week_start,'MM-DD') wk, to_char(t.scheduled_for,'MM-DD HH24:MI') sched, t.completed done, (select left(x.title,14) from tasks x where x.id=t.goal_task_id) under, (select left(x.title,14) from tasks x where x.id=t.supports_goal_task_id) supports, (select left(g.name,14) from goals g where g.id=t.goal_id) yeargoal, array_length(t.assigned_to_all,1) ppl, left(coalesce(t.notes,''),12) notes, left(t.id::text,8) id from tasks t order by t.created_at" -c "select left(name,40), context, year, status from goals"
